function normalizeText(str: string): string {
  return str
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Resuelve de forma exacta y fuzzy el video oficial del canal Catilli
 * buscando entre los 676 videos disponibles.
 */
export function resolveExerciseVideo(exerciseName: string, explicitUrl?: string): ExerciseVideoInfo {
  const target = normalizeText(exerciseName || '');

  // 1. Prioridad absoluta a mapeos canónicos de Catilli
  if (DIRECT_EXACT_MAP[target]) {
    const item = DIRECT_EXACT_MAP[target];
    return {
      title: item.title,
      videoId: item.id,
      embedUrl: `https://www.youtube.com/embed/${item.id}`,
      watchUrl: `https://www.youtube.com/watch?v=${item.id}`
    };
  }

  // 2. Si viene una URL que ya es de Catilli (o explícita válida de Catilli)
  if (explicitUrl && (explicitUrl.includes('youtube.com') || explicitUrl.includes('youtu.be'))) {
    let vidId = '';
    if (explicitUrl.includes('embed/')) {
      vidId = explicitUrl.split('embed/')[1]?.split('?')[0] || '';
    } else if (explicitUrl.includes('watch?v=')) {
      vidId = explicitUrl.split('watch?v=')[1]?.split('&')[0] || '';
    }
    if (vidId && vidId !== 'rT7DgCr-3pg' && vidId !== 'SW_C1A-rejs' && vidId !== 'JCXUYuzwNrM' && vidId !== 'G8l_8chR5BE') {
      return {
        title: exerciseName,
        videoId: vidId,
        embedUrl: `https://www.youtube.com/embed/${vidId}`,
        watchUrl: explicitUrl
      };
    }
  }

  // 3. Coincidencia exacta de texto normalizado en la biblioteca
  const exact = ALL_CATILLI_VIDEOS.find(v => v.norm === target);
  if (exact) {
    return {
      title: exact.title,
      videoId: exact.id,
      embedUrl: exact.embedUrl,
      watchUrl: exact.watchUrl
    };
  }

  // 4. Coincidencia de inclusión completa (target dentro de video o video dentro de target)
  const fullInclude = ALL_CATILLI_VIDEOS.find(v => v.norm.includes(target) || target.includes(v.norm));
  if (fullInclude) {
    return {
      title: fullInclude.title,
      videoId: fullInclude.id,
      embedUrl: fullInclude.embedUrl,
      watchUrl: fullInclude.watchUrl
    };
  }

  // 5. Coincidencia por tokens ponderados
  const targetWords = target.split(' ').filter(w => w.length > 2);
  let bestMatch: CatilliVideoEntry | null = null;
  let highestScore = 0;

  for (const v of ALL_CATILLI_VIDEOS) {
    let score = 0;
    if (v.norm === target) score += 100;
    if (v.norm.includes(target) || target.includes(v.norm)) score += 50;

    for (const w of targetWords) {
      if (v.norm.includes(w)) score += w.length;
    }
    if (score > highestScore) {
      highestScore = score;
      bestMatch = v;
    }
  }

  if (bestMatch && highestScore >= 5) {
    return {
      title: bestMatch.title,
      videoId: bestMatch.id,
      embedUrl: bestMatch.embedUrl,
      watchUrl: bestMatch.watchUrl
    };
  }

  // Fallback a Sentadilla Atrás de Catilli
  return {
    title: 'Sentadilla atrás',
    videoId: 'IX4rtWXcAlY',
    embedUrl: 'https://www.youtube.com/embed/IX4rtWXcAlY',
    watchUrl: 'https://www.youtube.com/watch?v=IX4rtWXcAlY'
  };
}
